    e.target.classList.add('dragging');
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', JSON.stringify({ item, index, fromList }));
    dragMessage.value = 'Dragging ' + item.label + '...';
